#include <stdio.h>
#include <stdlib.h>

struct Node { int data; struct Node *next; };

void insertFront(struct Node **headRef, int value) {
    struct Node *newNode = malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = *headRef;
    *headRef = newNode;
}

#define CAP 5
int queue[CAP], front = 0, rear = 0, count = 0;

void enqueue(int value) {
    if (count == CAP) { printf("Queue full\n"); return; }
    queue[rear] = value;
    rear = (rear + 1) % CAP;    // circular wraparound
    count++;
}

int main() {
    struct Node *head = NULL;
    insertFront(&head, 10);
    insertFront(&head, 20);
    printf("%d -> %d\n", head->data, head->next->data);   // 20 -> 10

    enqueue(1); enqueue(2);
    printf("front value: %d\n", queue[front]);
    return 0;
}
